	private void StartSpawning(GHPGNELIDBM fract, SpawningManagerDeathMatch.ArmyUnitDefinition def)
	{
		if (fract == GHPGNELIDBM.Allies)
		{
			SpawningManagerDeathMatch spawningManagerDeathMatch = Singleton<SpawningManagerDeathMatch>.instance;
			spawningManagerDeathMatch.JPGKPGFDAFM = (Action<GHPGNELIDBM, SpawningManagerDeathMatch.ArmyUnitDefinition>)Delegate.Remove(spawningManagerDeathMatch.JPGKPGFDAFM, new Action<GHPGNELIDBM, SpawningManagerDeathMatch.ArmyUnitDefinition>(StartSpawning));
			mCanUpdateSpawned = true;
			mSpawnedSoldiers = 0;
		}
	}

	private void FinishSpawning(GHPGNELIDBM fract, SpawningManagerDeathMatch.ArmyUnitDefinition def)
	{
		if (fract == GHPGNELIDBM.Allies)
		{
			SpawningManagerDeathMatch spawningManagerDeathMatch = Singleton<SpawningManagerDeathMatch>.instance;
			spawningManagerDeathMatch.AKKDJINOPDA = (Action<GHPGNELIDBM, SpawningManagerDeathMatch.ArmyUnitDefinition>)Delegate.Remove(spawningManagerDeathMatch.AKKDJINOPDA, new Action<GHPGNELIDBM, SpawningManagerDeathMatch.ArmyUnitDefinition>(FinishSpawning));
			mCanUpdateSpawned = false;
		}
	}

	private EnemyController CreateEnemyWithBehavior(LevelBehaviour behaviour, bool isPreview = false)
	{
		EnemyController enemyController = (EnemyController)Singleton<LevelBehaviourManager>.instance.GenerateNewEnemy(behaviour);
		if (enemyController != null && enemyController.prefab != null)
		{
			enemyController.fraction = GHPGNELIDBM.Allies;
			enemyController.LCDBACDIODH = isPreview;
			int nOCEDALFEJM = ObjectPoolDatabase.networkPool.APCGDLEHGKL[enemyController.prefab];
			enemyController = (EnemyController)ObjectPoolDatabase.networkPool.ReInstantiate(nOCEDALFEJM, enemyController.indexInObjectPool);
			if (isPreview)
			{
				enemyController.UpdatePreview(true);
			}
			return enemyController;
		}
		return null;
	}

