	private void ApplyPowersToEnemies()
	{
		List<PoolableObject> objectsMadeOfPrefab = ObjectPoolDatabase.networkPool.GetObjectsMadeOfPrefab(Singleton<ObjectPoolDatabase>.instance.KGGJOOAFDIF);
		foreach (PoolableObject item in objectsMadeOfPrefab)
		{
			EnemyController enemyController = item as EnemyController;
			if (enemyController != null && enemyController.fraction == GHPGNELIDBM.Enemies && enemyController.isInstantiated && enemyController.isAlive)
			{
				enemyController.power = 4;
			}
			if (enemyController.fraction == GHPGNELIDBM.Allies && enemyController.soldierBehaviour is SoldierBehaviourMachineGunner)
			{
				BulletSetup bulletSetup = (BulletSetup)enemyController.soldierBehaviour.KHKAAGCIJPO.ammoSetup;
				bulletSetup.EPDELOGPNAC = 20f;
				enemyController.soldierBehaviour.soldierBehaviourDefinititon.minShootTime = 1f;
				enemyController.soldierBehaviour.soldierBehaviourDefinititon.maxShootTime = 4f;
				enemyController.soldierBehaviour.soldierBehaviourDefinititon.fireBatchSizeMin = 1;
				enemyController.soldierBehaviour.soldierBehaviourDefinititon.fireBatchSizeMax = 4;
			}
		}
	}

