	public void CheckAfterDownload()
	{
		if (weaponBoughtState > 0 && base.isTutorialRunning)
		{
			LevelManager.instance.CheckCurrentLevelForTutorial(2);
			if (weaponBoughtState < 3)
			{
				mTutorialWeapon.bought = false;
			}
		}
	}

