	{
		if (mWaitingForSendUnit)
		{
			mWaitingForSendUnit = false;
		}
	}

	public void EquipTutorialWeaponAfterSkipTutorial()
	{
		foreach (WeaponLevelsSetup weaponLevelsSetup in LevelManager.instance.weaponLevelsSetups)
		{
			if (weaponLevelsSetup.FICHPKKDGBK)
			{
				mTutorialWeapon = weaponLevelsSetup;
				weaponLevelsSetup.bought = true;
				break;
			}
		}
		if (mTutorialWeapon == null)
		{
			return;
		}
		mTutorialWeapon.bought = true;
		int num = LevelManager.instance.weaponLevelsSetups.FindIndex((WeaponLevelsSetup w1) => w1.DHHKOKKDDDO() == mTutorialWeapon.DHHKOKKDDDO());
		if (num >= 0)
		{
			PlayerInventory.InventorySlot slotForCategory = PlayerInventory.instance.GetSlotForCategory(mTutorialWeapon.BHCEOOLEHHG);
			if (slotForCategory != null)
			{
				slotForCategory.weaponIndex = num;
			}
		}
	}
